#!/usr/bin/env bash
# Apply the Scorecard cron pipeline to the Kyma dev cluster.
#
# The cron ConfigMap names the Object Store buckets, whose hcp-<uuid>
# names are generated by the broker and live only in the binding secrets
# (never committed). This script fills cron-config.yaml.template from the
# secrets and applies it alongside the other cron manifests.
#
# Prerequisites:
#   - deploy-kyma-baseline applied (binding secrets present)
#   - KUBECONFIG points at the Kyma dev cluster
#   - a github secret exists (see below)
#
# NOT YET RUNNABLE END-TO-END: the worker's multi-bucket credential model
# is an open decision (deploy-kyma-cron KC7). This script and the
# manifests are complete up to that point.
set -euo pipefail

NS=scorecard-infra-dev
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

need() { command -v "$1" >/dev/null || { echo "missing: $1" >&2; exit 1; }; }
need kubectl

secret_val() {
  kubectl -n "$NS" get secret "$1" -o jsonpath="{.data.$2}" | base64 -d
}

echo "== reading cron-results bucket from binding secret =="
CRON_BUCKET=$(secret_val scorecard-cron-results-binding bucket)
CRON_REGION=$(secret_val scorecard-cron-results-binding region)

echo "   cron-results: $CRON_BUCKET ($CRON_REGION)"
echo "   (single-bucket layout, KC7: all roles under prefixes in this one bucket)"

echo "== rendering ConfigMap from template =="
sed -e "s/__CRON_BUCKET__/${CRON_BUCKET}/g" \
    -e "s/__CRON_REGION__/${CRON_REGION}/g" \
    "$HERE/cron-config.yaml.template" | kubectl apply -f -

echo "== github secret check =="
if ! kubectl -n "$NS" get secret github >/dev/null 2>&1; then
  cat >&2 <<'MSG'
No `github` secret found. The worker needs a GitHub token (KC2). Create it
yourself — the token never enters the repo or chat:

  kubectl -n scorecard-infra-dev create secret generic github \
    --from-literal=token="$(gh auth token)" \
    --dry-run=client -o yaml | kubectl apply -f -

Then re-run this script.
MSG
  exit 1
fi

echo "== applying cron manifests =="
kubectl apply -f "$HERE/cron-rbac.yaml"
kubectl apply -f "$HERE/cron-nats.yaml"
kubectl -n "$NS" rollout status deploy/scorecard-nats --timeout=3m
kubectl apply -f "$HERE/cron-controller.yaml"
kubectl apply -f "$HERE/cron-worker.yaml"
kubectl -n "$NS" rollout status deploy/scorecard-batch-worker --timeout=5m

echo "== done =="
echo "Trigger a run now instead of waiting for Monday 02:00 UTC:"
echo "  kubectl -n $NS create job --from=cronjob/scorecard-batch-controller cron-manual-\$(date +%s)"
